const ElementReferenceIndex = Symbol("ElementReferenceIndex");
interface ReactiveDescriptor {
  original?: PropertyDescriptor;
  get: () => any;
  active: boolean;
  successors?: Set<ReactiveDescriptor>;
}
const reactiveDescriptors = new WeakMap<IBindDef, ReactiveDescriptor>();
const reactiveGetters = new WeakMap<() => any, ReactiveDescriptor>();
// BindMap remains the public single-context map. Only bindings spanning more
// than one inherited context need additional cleanup metadata.
const additionalBindContexts = new WeakMap<IGtplObject, Map<IBindObject, Set<IGtplObject>>>();
const initialBindings = new WeakSet<IBindObject>();
const directListStates = new WeakMap<IBindObject, { rows: any[]; ordinary: boolean }>();

// g-is content can be destroyed independently of its rendering owner.
// Keep its insertion point outside that content, including combined g-if binds.
const persistentMarks = new WeakSet<Node>();

interface InitialRenderState {
  pending: number;
  settled: boolean;
  failure?: { error: unknown };
  reject?: (error: unknown) => void;
  idle?: Promise<void>;
  resolveIdle?: () => void;
}

function finishInitialUpdate(job: PendingBindingChange | undefined, error?: { error: unknown }) {
  job?.initialStates?.forEach(state => {
    if (error) {
      if (!state.failure) state.failure = error;
      state.reject?.(error.error);
    }
    if (--state.pending === 0) {
      state.resolveIdle?.();
      state.idle = undefined;
      state.resolveIdle = undefined;
    }
  });
  job?.initialStates?.clear();
}

interface PendingBindingChange {
  context: GTpl;
  type: TypeEventProxyHandler;
  path?: string[];
  value?: any;
  promise?: Promise<void>;
  resolve?: () => void;
  reject?: (error: unknown) => void;
  initialStates?: Set<InitialRenderState>;
  listUpdate?: boolean;
  listIndices?: Set<number>;
  listTouched?: Set<number>;
  listNestedOnly?: boolean;
  checkedCaller?: GTpl;
  reportErrors: boolean;
  observingErrors?: boolean;
}

// A binding can subscribe through several inherited contexts. Deduplicate by
// binding identity across those contexts, while keeping the owning context.
const pendingBindingChanges = new Map<IBindObject, PendingBindingChange>();
const currentBindingChanges = new WeakMap<IBindObject, PendingBindingChange>();
let bindingFlushScheduled = false;
let activeBindingFlush: {
  queues: IBindObject[][];
  positions: number[];
  seen: Set<IBindObject>;
  depth: number;
} | undefined;

function isPromiseLike(value: any): value is PromiseLike<any> {
  return value != null && (typeof value === 'object' || typeof value === 'function') && typeof value.then === 'function';
}

function cancelBindingChange(bind: IBindObject) {
  const job = currentBindingChanges.get(bind);
  if (job) {
    if (job.initialStates?.size) finishInitialUpdate(job);
    job.resolve?.();
    pendingBindingChanges.delete(bind);
    currentBindingChanges.delete(bind);
  }
  initialBindings.delete(bind);
}

function observeBindingErrors(job: PendingBindingChange) {
  if (job.reportErrors && job.promise && !job.observingErrors) {
    job.observingErrors = true;
    job.promise.catch(error => console.error('[GTPL] Binding update failed:', error));
  }
}

function bindingChangePromise(job: PendingBindingChange): Promise<void> {
  if (!job.promise)
    job.promise = new Promise<void>((resolve, reject) => { job.resolve = resolve; job.reject = reject; });
  observeBindingErrors(job);
  return job.promise;
}

function finishBindingChange(bind: IBindObject, job: PendingBindingChange, error?: { error: unknown }) {
  const current = currentBindingChanges.get(bind) === job;
  if (current) {
    currentBindingChanges.delete(bind);
    if (job.initialStates?.size) initialBindings.delete(bind);
  }
  const failed = error && current && !job.context.isDestroyed && !bind.gtpl?.isDestroyed;
  if (job.initialStates?.size) finishInitialUpdate(job, failed ? error : undefined);
  if (failed) {
    if (job.reject) job.reject(error!.error);
    else if (job.reportErrors) console.error('[GTPL] Binding update failed:', error!.error);
  } else {
    job.resolve?.();
  }
}

const globalCache: any = {
  binitChangeEvents: false,
  changeEventsCount: 0,
  changeEventsHandler: null,
};

