function createGetterAndSetter(
  gtpl: IGtplObject,
  va: TplVar,
  bind: IBindObject
) {
  const key = va[0];
  const ref = gtpl.BindTree[key];
  if (ref != undefined) {
    return;
  }
  const defaultvalue = gtpl.getValue(key);
  const objdef: IBindDef = {
    key: key,
    val: defaultvalue, // target
    pro: undefined, // proxy
  };
  gtpl.BindDef.add(objdef);
  try {
    const original = Object.getOwnPropertyDescriptor(gtpl.Root, key);
    // Restoration uses the latest state; retaining the old data value here
    // would keep replaced payloads alive through overlapping view lifetimes.
    if (original && 'value' in original) original.value = undefined;
    if (!gtpl.Root.hasOwnProperty(key))
      gtpl.Root[key] = null;
    const get = function () {
        if (objdef.pro !== undefined) return objdef.pro;
        if (isStaticType(objdef.val)) return objdef.val;
        objdef.val = toRaw(objdef.val);
        objdef.pro = GProxy(objdef.val, gtpl.BoundEventProxy, objdef, [
          objdef.key,
        ]);
        return objdef.pro;
    };
    Object.defineProperty(gtpl.Root, key, {
      get,
      set: function (newval: any) {
        const rawNewValue = toRaw(newval);
        const doSet = () => {
          objdef.val = rawNewValue;
          if (isStaticType(rawNewValue)) {
            delete objdef.pro;
            return objdef.val;
          } else {
            objdef.val = toRaw(objdef.val);
            objdef.pro = GProxy(
              objdef.val,
              gtpl.BoundEventProxy,
              objdef,
              [objdef.key]
            );
            return objdef.pro;
          }
        };
        const ret = replaceGProxy(objdef.val, gtpl.BoundEventProxy, objdef, objdef.key, doSet);
        gtpl.eventPRoxy(
          TypeEventProxyHandler.SET,
          [objdef.key],
          rawNewValue,
          objdef
        );
        return ret;
      },
    });
    const descriptor = { original, get, active: true };
    reactiveDescriptors.set(objdef, descriptor);
    reactiveGetters.set(get, descriptor);
    const previous = original?.get && reactiveGetters.get(original.get);
    if (previous) (previous.successors || (previous.successors = new Set())).add(descriptor);
  } catch (ex) {
    STACK((<any>ex).message, key, gtpl.Root);
  }
}

function addBind2Object(gtpl: IGtplObject, va: TplVar, bind: IBindObject) {
  if (va.length == 0 || (va.length == 1 && va[0] == 'this'))
    return;
  let ref: any = gtpl.BindTree;
  for (let i = 0, n = va.length; i < n; i++) {
    const name = va[i];
    if (i == 0) {
      const ctx = gtpl.getContext(name);
      if (ctx != gtpl) {
        // si se añade el bind a otro contexto, hay que almacenar el contexto original
        bind.gtpl = gtpl;
        // almacenamos en el contexto original una referencia al contexto donde se almacena el bind
        if (!gtpl.BindMap) gtpl.BindMap = new Map();
        const previous = gtpl.BindMap.get(bind);
        if (previous && previous !== ctx) {
          let bindings = additionalBindContexts.get(gtpl);
          if (!bindings) additionalBindContexts.set(gtpl, bindings = new Map());
          let contexts = bindings.get(bind);
          if (!contexts) bindings.set(bind, contexts = new Set());
          contexts.add(previous);
          contexts.add(ctx);
        }
        gtpl.BindMap.set(bind, ctx);
        addBind2Object(ctx, va, bind);
        return;
      }
      // Only the owning context registers the reactive property. Registering
      // before delegating creates a second descriptor/subscription because its
      // BindTree entry does not exist until the recursive call finishes.
      createGetterAndSetter(ctx, va, bind);
    }
    if (ref[name] == undefined)
      ref[name] = {};
    if (i < n - 1) {
      ref = ref[name];
      if (ref.tree == undefined) ref.tree = {};
      ref = ref.tree;
    } else {
      ref = ref[name];
    }
  }
  if (ref.me == undefined) {
    ref.me = new Set();
  }
  ref.me.add(bind);
}

function getBind2Object(
  gtpl: IGtplObject,
  va: TplVar,
  bind: IBindObject
): Set<IBindObject> | null {
  /*
    if (bind.gtpl && bind.gtpl != gtpl) {
        console.error('getBind2Object', 2);
        const original_gtpl = bind.gtpl;
        delete bind.gtpl;
        return getBind2Object(original_gtpl, va, bind);
    }
    */
  /*
     if (gtpl.BindMap && gtpl.BindMap.has(bind)) {
         console.error('getBind2Object', 1);
         const ctx_gtpl = gtpl.BindMap.get(bind);
         if (ctx_gtpl && ctx_gtpl != gtpl) {
             gtpl.BindMap.delete(bind);
             return getBind2Object(ctx_gtpl, va, bind);
         }
     }
     */
  if (va.length == 0 || (va.length == 1 && va[0] == 'this'))
    return null;
  let ref: any = gtpl.BindTree;
  for (let i = 0, n = va.length; i < n; i++) {
    const name = va[i];
    // A formula can bind variables from different GTpl contexts (for example,
    // a parent helper and a g-for row). During cleanup each context only owns
    // part of those paths, so a missing branch is expected.
    if (!ref || ref[name] == undefined)
      return null;
    ref = ref[name];
    if (i < n - 1) {
      if (ref.tree == undefined)
        return null;
      ref = ref.tree;
    }
  }
  return ref?.me ?? null;
}

function delBind(gtpl: IGtplObject, bind: IBindObject) {
  cancelBindingChange(bind);
  if (bind.type === BindTypes.FOR) directListStates.delete(bind);
  if (bind.link.vorc && bind.link.vorc.va) {
    getBind2Object(gtpl, bind.link.vorc.va, bind)?.delete(bind);
  }
  if (bind.link.formula?.vars) {
    bind.link.formula.vars.forEach((va) => {
      getBind2Object(gtpl, va, bind)?.delete(bind);
    });
  }
  bind.link.functions?.forEach(fnc => fnc.params?.forEach(param => {
    if (param.va) getBind2Object(gtpl, param.va, bind)?.delete(bind);
  }));
  if (bind.simetric && bind.ele) {
    const setBindings = simetricAttr.get(bind.ele);
    if (setBindings) {
      const entry = (bind as any)._simetricEntry as IsimetricAttrValue | undefined;
      if (entry && setBindings.has(entry)) {
        setBindings.delete(entry);
        if (!setBindings.size) {
          simetricAttr.delete(bind.ele);
        }
      } else {
        const nuevo = new Set(
          Array.from(setBindings).filter((item) => item.ctx !== gtpl)
        );
        if (nuevo.size) {
          simetricAttr.set(bind.ele, nuevo);
        } else {
          simetricAttr.delete(bind.ele);
        }
      }
    }
    if ((bind as any)._simetricRefTracked) {
      removeChangeEventsRef();
      delete (bind as any)._simetricRefTracked;
    }
    unpatchSimetricProperty(bind);
    delete (bind as any)._simetricEntry;
  }
}

function searchBind(gtpl: IGtplObject, bind: IBindObject): boolean {
  let encontrado = false;
  if (bind.link.vorc && bind.link.vorc.va) {
    if (getBind2Object(gtpl, bind.link.vorc.va, bind)?.has(bind))
      encontrado = true;
  }
  if (bind.link.formula?.vars) {
    bind.link.formula.vars.forEach((va) => {
      if (getBind2Object(gtpl, va, bind)?.has(bind))
        encontrado = true;
    });
  }
  if (!encontrado) {
    const re: Set<IBindObject> = privateProperties.getProperty(
      gtpl,
      "renderElements", false
    );
    re?.delete(bind);
  }
  return encontrado;
}

