function checkBindElements(gtpl: IGtplObject, bind: IBindObject): boolean {
  if (bind.type === BindTypes.ELE && bind.link?.vorc?.va && bind.ele) {
    const va = bind.link.vorc.va;
    updateVar(va, gtpl, bind.ele, true);
    gtpl.onCleanup(() => {
      // A later binding may have replaced the reference on the same path.
      if (reduceVar(gtpl, va) === bind.ele) updateVar(va, gtpl, null);
    });
    return true;
  }
  if (bind.type === BindTypes.ELES && bind.link?.vorc?.va && bind.ele) {
    const va = bind.link.vorc.va;
    let arr = reduceVar(gtpl, va);
    if (!Array.isArray(arr)) {
      updateVar(va, gtpl, [], true);
      arr = reduceVar(gtpl, va);
    }
    if (!arr.includes(bind.ele)) {
      arr.push(bind.ele);
      const collection = toRaw(arr);
      gtpl.onCleanup(() => {
        let current = collection;
        try {
          const value = reduceVar(gtpl, va);
          if (toRaw(value) === collection) current = value;
        } catch {
          // The containing state path may already have been removed.
        }
        const index = current.indexOf(bind.ele);
        if (index !== -1) current.splice(index, 1);
      });
    }
    return true;
  }
  return false;
}

function checkBindEvent(gtpl: IGtplObject, bind: IBindObject): boolean {
  if (bind.type == BindTypes.EVENT && bind.prop) {
    //log('checkBindEvent', gtpl, bind);
    const ctx: IGtplObject = getContext(gtpl, bind);
    const obj = { gtpl: ctx, bind: bind };
    const options: any = { passive: false };
    //---
    const handler = function (event: any) {
      const apply = (result: any) => {
        if (gtpl.isDestroyed || obj.gtpl.isDestroyed) return;
        if (typeof result == "function") {
          if (obj.bind.link.params) {
            const arrval: any = [];
            obj.bind.link.params.forEach((param) => {
              if (param.ct != undefined) arrval.push(param.ct);
              else if (param.va != undefined)
                arrval.push(reduceVar(gtpl, param.va));
            });
            result.apply(obj.gtpl.Root, [event, ...arrval]);
          } else {
            result.apply(obj.gtpl.Root, [event]);
          }
        } else {
          if (result === false) {
            if (event.preventDefault)
              event.preventDefault();
            if (event.stopPropagation)
              event.stopPropagation();
          }
        }
      };
      const result = calculateBind(obj.gtpl, obj.bind, undefined, event);
      if (isPromiseLike(result))
        Promise.resolve(result).then(apply).catch(error => console.error('[GTPL] Event handler failed:', error));
      else apply(result);
    };
    //---
    bind.ele.addEventListener(
      bind.prop,
      handler,
      passiveSupported ? options : false
    );
    //---
    if (!bind.ele[ElementReferenceIndex])
      bind.ele[ElementReferenceIndex] = [];
    const reference = {
      type: bind.prop,
      handler,
      options: passiveSupported ? options : false
    };
    bind.ele[ElementReferenceIndex].push(reference);
    gtpl.onCleanup(() => {
      bind.ele.removeEventListener(reference.type, reference.handler, reference.options);
      const references = bind.ele[ElementReferenceIndex];
      if (!references) return;
      const index = references.indexOf(reference);
      if (index !== -1) references.splice(index, 1);
      if (!references.length) delete bind.ele[ElementReferenceIndex];
    });
    //---
    return true;
  }
  return false;
}

function checkBindFormula(gtpl: IGtplObject, bind: IBindObject): boolean {
  let result = false;
  if (bind.link.formula && bind.link.formula.vars && bind.link.formula.vars.length) {
    result = true;
    bind.link.formula.vars.forEach((va) => {
      addBind2Object(gtpl, va, bind);
    });
  }
  return result;
}

function checkSimetricBind(gtpl: IGtplObject, bind: IBindObject) {
  if (
    bind.type == BindTypes.ATTR &&
    bind.prop &&
    bind.link &&
    bind.link.vorc &&
    bind.link.vorc.va
  ) {
    const { prop } = bind;
    if (prop.startsWith('[') && prop.endsWith(']')) {
      //---
      if (!(bind as any)._simetricRefTracked) {
        addChangeEventsRef();
        (bind as any)._simetricRefTracked = true;
      }
      //---
      bind.simetric = true;
      bind.prop = prop.slice(1, - 1);
      //---
      const va = bind.link.vorc.va;
      const ctx: any = gtpl.getContext(va[0]);
      //---
      if (!simetricAttr.has(bind.ele)) simetricAttr.set(bind.ele, new Set());
      const entry = {
        va: va,
        ctx: ctx,
        prop: bind.prop
      };
      simetricAttr.get(bind.ele)?.add(entry);
      (bind as any)._simetricEntry = entry;
      patchSimetricProperty(bind, va, ctx);
      //---
    }
  }
}

function checkBind(gtpl: IGtplObject, bind: IBindObject): boolean {
  let result = false;
  if (bind.link.vorc && bind.link.vorc.va) {
    result = true;
    checkSimetricBind(gtpl, bind);
    addBind2Object(gtpl, bind.link.vorc.va, bind);
  }
  if (bind.link.functions) {
    bind.link.functions.forEach((fnc: IFunction) => {
      if (fnc.params) {
        fnc.params.forEach((param: IVarOrConst) => {
          if (param.va) {
            result = true;
            addBind2Object(gtpl, param.va, bind);
          }
        });
      }
    });
  }
  return result;
}

function collectBindsFromTree(tree: any, out: Set<IBindObject>) {
  if (!tree) {
    return;
  }
  if (tree.me) {
    tree.me.forEach((bind: IBindObject) => out.add(bind));
  }
  if (tree.tree) {
    Object.keys(tree.tree).forEach((key) => {
      collectBindsFromTree(tree.tree[key], out);
    });
  }
}

