function removeElements(elements: any) {
  if (elements == null) return;
  if (Array.isArray(elements)) {
    fragmentNodes(elements).forEach((element) => {
      removeElements(element);
    });
  } else {
    if (elements[ElementReferenceIndex]) {
      for (const { type, handler, options } of elements[ElementReferenceIndex]) {
        elements.removeEventListener(type, handler, options);
      }
      delete elements[ElementReferenceIndex];
    }
    if (typeof Element !== "undefined" && elements instanceof Element) {
      while (elements.attributes.length > 0) {
        elements.removeAttribute(elements.attributes[0].name);
      }
    }
    if (elements.destroy) {
      if (!elements.isDestroyed) elements.destroy(true);
    } else {
      elements.parentNode?.removeChild(elements);
    }
  }
}

