function updateTEXTbind(
  type: TypeEventProxyHandler,
  gtpl: IGtplObject,
  bind: IBindObject,
  result?: any,
  path?: string[]
) {
  //log('TEXT', bind, result, path);
  //---
  gtpl = getContext(gtpl, bind);
  //---
  const memValues = privateProperties.getProperty(gtpl, "memValues");
  if (result !== undefined && result !== null) {
    if (memValues.has(bind) && memValues.get(bind) == result) {
      return gtpl;
    }
    memValues.set(bind, result);
  }
  //---
  bind.ele.textContent = result;
  //---
  return gtpl;
}

function updateATTRbind(
  type: TypeEventProxyHandler,
  gtpl: IGtplObject,
  bind: IBindObject,
  result?: any,
  path?: string[]
) {
  gtpl = getContext(gtpl, bind);
  const updateProperty = (prop: string, value: any) => {
    if (bind.ele[prop] !== undefined && bind.ele[prop] !== null) {
      if (value == null) {
        if (bind.ele[prop] !== "")
          bind.ele[prop] = null;
      } else if (bind.ele[prop] != value) {
        try {
          bind.ele[prop] = value;
        } catch (ex) {
          STACK((<any>ex).message, bind.ele, prop);
        }
      }
    } else {
      if (value == null) {
        bind.ele.removeAttribute(prop);
      } else if (bind.ele.getAttribute(prop) != value) {
        bind.ele.setAttribute(prop, value);
      }
    }
  };
  if (bind.prop) {
    updateProperty(bind.prop, result);
  } else {
    if (result == null) {
      if (bind.attrs) {
        bind.attrs.forEach((key) => {
          updateProperty(key, null);
        });
        delete bind.attrs;
      }
    } else {
      if (!bind.attrs)
        bind.attrs = [];
      const missing = bind.attrs.filter(key => !(key in result));
      missing.forEach((key) => {
        updateProperty(key, null);
      });
      bind.attrs.length = 0;
      // GProxy forwards key/descriptor enumeration unchanged. Avoid those
      // traps, but keep value reads on the proxy so getters retain their receiver.
      for (let key in toRaw(result)) {
        bind.attrs.push(key);
        updateProperty(key, result[key]);
      }
    }
  }
  return gtpl;
}

function updateINNERbind(type: TypeEventProxyHandler,
  gtpl: IGtplObject,
  bind: IBindObject,
  result?: any,
  path?: string[]
) {
  gtpl = getContext(gtpl, bind);
  if (result !== undefined && bind.ele.innerHTML != result)
    bind.ele.innerHTML = result;
  return gtpl;
}

function updateSTYLEbind(
  type: TypeEventProxyHandler,
  gtpl: IGtplObject,
  bind: IBindObject,
  result?: any,
  path?: string[]
) {
  //log('STYLE', bind, result, path);
  //---
  gtpl = getContext(gtpl, bind);
  //---
  const memValues = privateProperties.getProperty(gtpl, "memValues");
  if (memValues.has(bind) && memValues.get(bind) == result) return gtpl;
  memValues.set(bind, result);
  //---
  if (bind.prop) {
    bind.ele.style[bind.prop] = result;
  }
  //---
  return gtpl;
}

function updateIFbind(
  type: TypeEventProxyHandler,
  gtpl: IGtplObject,
  bind: IBindObject,
  result?: any,
  path?: string[]
) {
  //log('IF/NOTIF', bind, result, path);
  //---
  gtpl = getContext(gtpl, bind);
  //---
  const bresult = bind.type == BindTypes.NOTIF ? !result : !!result;
  //---
  if (!bind.mark.checks) bind.mark.checks = {};
  bind.mark.checks[bind.type] = bresult;
  //---
  checkMarkEle(gtpl, bind, bresult);
  //---
  if (!bind.ele) {
    return gtpl;
  }
  //---
  const memValues = privateProperties.getProperty(gtpl, "memValues");
  if (memValues.has(bind) && memValues.get(bind) === bresult) return gtpl;
  //---
  if (renderBind(gtpl, bind, bresult)) memValues.set(bind, bresult);
  //---
  return gtpl;
}

function isDirectList(bind: IBindObject): boolean {
  return !!bind.link.vorc?.va && !bind.link.formula?.fnc && !bind.link.functions?.length;
}

// Accessors may depend on unrelated paths. Inspect descriptors, never execute
// getters to decide whether a list can use the incremental reconciliation path.
// Raw mutations are reclassified by refresh()/explicit assignments. Between
// those, proxy notifications identify the rows whose descriptors can change.
function isOrdinaryData(value: any, seen = new Set<object>()): boolean {
  value = toRaw(value);
  if (value === null || typeof value !== 'object') return typeof value !== 'function';
  if (seen.has(value)) return true;
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== Array.prototype && prototype !== null) return false;
  seen.add(value);
  for (const key of Reflect.ownKeys(value)) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key)!;
    if (!('value' in descriptor) || !isOrdinaryData(descriptor.value, seen)) return false;
  }
  return true;
}

function updateFORbind(
  type: TypeEventProxyHandler,
  gtpl: IGtplObject,
  bind: IBindObject,
  result?: any,
  path?: string[],
  incremental = false,
  assignedIndices?: Set<number>
) {
  //console.log('FOR', type, bind, result, path);
  //---
  // Data can come from an ancestor while the generated rows belong to the
  // rendering component. Keep that ownership so removing a switch branch also
  // destroys its rows and unregisters their bindings from ancestor contexts.
  const owner = bind.gtpl || gtpl;
  gtpl = getContext(gtpl, bind);
  //---
  //if (!searchBind(gtpl, bind)) {
  //    return;
  //}
  //---
  if (!bind.eles) bind.eles = [];
  //---
  const elementos = bind.eles;
  const objindex: IIndex = <IIndex>bind.link.index;
  //---
  const render_arr: any = [];
  const delete_arr: any = [];
  //---
  const length = result?.length || 0;
  for (let index = 0; index < length; index++) {
    const row = toRaw(result[index]);
    if (index >= elementos.length) {
      const child = createGTpl(gtpl, bind, objindex, elementos, row, false);
      elementos.push(child);
      render_arr.push([child, index]);
    } else {
      const root = elementos[index].Root;
      // Explicit refreshes and same-reference assignments must observe raw
      // mutations. Only ordinary proxy notifications can skip unchanged rows.
      if (!incremental || assignedIndices?.has(index) || !Object.is(toRaw(root[objindex.target]), row))
        root[objindex.target] = row;
    }
  }
  if (elementos.length > length) {
    elementos.splice(length).forEach((child, index) => delete_arr.push([child, index]));
  }
  //---
  if (delete_arr.length) {
    delete_arr.forEach((rowinfo: any) => {
      const [newgtpl, index] = rowinfo;
      newgtpl.destroy();
      owner.GtplChilds.delete(newgtpl);
    });
  }
  //---
  if (render_arr.length) {
    //---
    const renderindex = getElementIndex(gtpl, bind);
    if (renderindex >= 0) {
      if (!gtpl.RenderElements[renderindex]) {
        gtpl.RenderElements[renderindex] = bind;
      }
    }
    //---
    const all: any = [];
    render_arr.forEach((rowinfo: any) => {
      const [newgtpl, index] = rowinfo;
      newgtpl.addTo(all);
      owner.GtplChilds.add(newgtpl);
    });
    //---
    if (bind.mark.parentNode) {
      //---
      show(
        {
          type: bind.type,
          link: bind.link,
          ele: all,
          mark: bind.mark,
        },
        false
      );
      //---
      render_arr.forEach((rowinfo: any) => {
        rowinfo[0].refresh();
      });
      //---
    } else if (renderindex >= 0 && searchBind(gtpl, bind)) {
      addCheckRenderElement(gtpl, bind);
    }
    //---
  }
  //---
  return gtpl;
}

function updateSWITCHbind(
  type: TypeEventProxyHandler,
  gtpl: IGtplObject,
  bind: IBindObject,
  result?: any,
  path?: string[],
  job?: PendingBindingChange
) {
  //log('SWITCH', bind, result, path);
  //---
  const owner = bind.gtpl || gtpl;
  gtpl = getContext(gtpl, bind);
  //---
  const bresult = result !== undefined && result !== null ? true : false;
  //---
  if (!bind.mark.checks) bind.mark.checks = {};
  bind.mark.checks[bind.type] = bresult;
  //---
  checkMarkEle(gtpl, bind, bresult);
  //---
  if (!bind.mark.checks) bind.mark.checks = {};
  bind.mark.checks[bind.type] = result == undefined ? false : true;
  //---
  if (!bind.ele) {
    return gtpl;
  }
  //---
  const memValues = privateProperties.getProperty(gtpl, "memValues");
  if (memValues.has(bind) && memValues.get(bind) === result) {
    return gtpl;
  }
  // Do not cache a selection until its asynchronous case calculation commits.
  memValues.delete(bind);
  //---
  if (bind.case && bind.case.length) {
    //---
    if (bind.eles && bind.eles.length) {
      bind.eles.forEach((gtplcase: IGtplObject) => {
        hide((<any>gtplcase).refCase);
        gtplcase.destroy();
        owner.GtplChilds.delete(gtplcase);
      });
      delete bind.eles;
    }
    //---
    if (!searchBind(gtpl, bind)) {
      return gtpl;
    }
    //---
    if (bresult) {
      //---
      if (!bind.case[0].mark) {
        //---
        const mcobj: any = {};
        //---
        collectCommentMarks(bind.ele, mcobj);
        //---
        for (let i = 0, n = bind.case.length; i < n; i++) {
          const ca = bind.case[i];
          if (!ca.mark && ca.uid) {
            ca.mark = mcobj[ca.uid];
          }
        }
        //---
      }
      //---
      return selectCase(0);
      //---
    }
    //---
  }
  //---
  return commit();

  function valid() {
    return !gtpl.isDestroyed && !owner.isDestroyed && currentBindingChanges.get(bind) === job;
  }

  function selectCase(start: number): IGtplObject | Promise<IGtplObject> {
    for (let i = start; i < bind.case!.length; i++) {
      if (!valid()) return gtpl;
      const ca = bind.case![i];
      const calculated = calculateBind(gtpl, ca);
      if (isPromiseLike(calculated)) {
        return Promise.resolve(calculated).then(value => {
          if (!valid()) return gtpl;
          return value == result ? mountCase(ca) : selectCase(i + 1);
        });
      }
      if (!valid()) return gtpl;
      if (calculated == result) return mountCase(ca);
    }
    return commit();
  }

  function mountCase(ca: IBindObject): IGtplObject {
    const child = createGTpl(gtpl, ca, undefined, undefined, undefined, false);
    if (!valid()) { child.destroy(); return gtpl; }
    ca.ele = child.Elements;
    ca.eles = [child];
    (child as any).refCase = ca;
    owner.GtplChilds.add(child);
    bind.eles = ca.eles;
    return commit();
  }

  function commit(): IGtplObject {
    if (!valid()) return gtpl;
    const rendered = renderBind(gtpl, bind, bresult);
    if (bresult && bind.eles?.length) {
      const child = (<any>bind.eles)[0];
      // A combined g-if can detach the wrapper while its selection changes.
      // Populate the case in that detached range before the wrapper is shown.
      if (rendered || child.refCase.mark.parentNode) {
        child.refresh();
        show(child.refCase);
      }
    }
    //---
    memValues.set(bind, result);
    return gtpl;
  }
}

function updateISbind(
  type: TypeEventProxyHandler,
  gtpl: IGtplObject,
  bind: IBindObject,
  result?: any,
  path?: string[]
) {
  //log('IS', bind, result, path);
  //---
  const owner = bind.gtpl || gtpl;
  gtpl = getContext(gtpl, bind);
  //---
  const bresult = result !== undefined && result !== null ? true : false;
  //---
  const memValues = privateProperties.getProperty(gtpl, "memValues");
  if (memValues.has(bind) && memValues.get(bind) == result) return gtpl;
  memValues.set(bind, result);
  if (!bind.mark.checks) bind.mark.checks = {};
  bind.mark.checks[bind.type] = bresult;
  //---
  let check = false;
  // si hay bind.eles es que se envió un array/función es que se envió una función generadora.
  if (bind.eles) {
    check = true;
    bind.eles[0].destroy();
    owner.GtplChilds.delete(bind.eles[0]);
    delete bind.eles;
  } else if (bind.ele) {
    hide(bind);
    if (bind.attrs) {
      for (const attr of bind.attrs) {
        if (!Array.isArray(attr)) {
          delBind(gtpl, attr as any);
        }
      }
    }
  }
  // DOM removal and child cleanup can synchronously destroy the owner.
  if (owner.isDestroyed || gtpl.isDestroyed) return gtpl;
  //---
  if (!bresult) {
    delete bind.ele;
    privateProperties.getProperty(gtpl, "MarkEle").delete(bind.mark);
    renderBind(gtpl, bind, false);
    return gtpl;
  }
  //---
  if (check && !searchBind(gtpl, bind)) {
    return gtpl;
  }
  //---
  // Inserting a DocumentFragment empties it. Track its roots like an array
  // generator so subsequent replacement and disposal still own those nodes.
  const generator = result.nodeType === 11 ? Array.from(result.childNodes) : result;
  if (Array.isArray(generator) || typeof generator == "function") {
    const newgtpl = createGTpl(gtpl, {
      link: bind.link,
      type: bind.type,
      gtpl: bind.gtpl,
      gen: generator,
    });
    bind.eles = [newgtpl];
    owner.GtplChilds.add(newgtpl);
    bind.ele = newgtpl.Elements;
  } else {
    const val = toRaw(result);
    if (bind.attrs)
      GAddArributes(bind.attrs, val, gtpl);
    bind.ele = val;
  }
  //---
  privateProperties.getProperty(gtpl, "MarkEle").set(bind.mark, bind.ele);
  //---
  renderBind(gtpl, bind, bresult);
  //---
  return gtpl;
}

//---

export class GTpl implements IGtplObject {
  ID!: string;

  /**
   * Referencia a la función generadora.
   */
  FncElements!: Function | Array<any>;

  /**
   * Array de array de elementos html que forman la plantilla
   */
  Elements!: Node[];

  /**
   * Objeto indexado a los elementos dinamicos de ka plantillas, for, switch etc...
   */
  RenderElements!: any;

  /**
   * Es el arbol de objetos bindados siguiendo la misma ramificación que en el arbol html.
   */
  BindTree!: any;

  /**
   * Son los objetos bindados con constantes, no dinámicos.
   */
  BindConst!: Set<IBindObject>;

  /**
   * Mapa de objetos bindados a plantillas diferentes a la original.
   * Por ejemplo: cuando se tiene una plantilla dentro de otra plantilla.
   */
  BindMap!: Map<IBindObject, IGtplObject>;

  /**
   * Son las claves de primer nivel de objetos bindados a la plantilla.
   */
  BindDef!: Set<IBindDef>;

  /**
   * Plantillas hijas.
   */
  GtplChilds!: Set<IGtplObject>;

  /**
   * Plantilla padre.
   */
  Parent!: IGtplObject;

  /**
   * Utilizado para localizar el contexto de la variable que se solicita.
   */
  Context!: Set<String>;

  /**
   * Objeto referencia para aplicar a la plantilla.
   */
  Root: any;

  BoundEventProxy: EventFunctionProxyHandler;

  cleanupCallbacks!: Set<() => void>;

  watchers!: Map<string, Set<Function>>;

  isDestroyed: boolean = false;

  private initialState: InitialRenderState = { pending: 0, settled: false };
  private initialReady?: Promise<void>;
  private bindingDepth = 0;

  constructor(options?: any) {
    //log('constructor', this, options);
    this.ID = Math.random().toString(16).slice(2);
    this.BindTree = {};
    this.BindConst = new Set();
    this.BindDef = new Set();
    this.GtplChilds = new Set();
    this.cleanupCallbacks = new Set();
    this.watchers = new Map();
    this.BoundEventProxy = this.eventPRoxy.bind(this);
    this.loadOptions(options);
  }

  loadOptions(options?: any) {
    try {
      if (options) {
        this.Root = options.root;
        if (options.parent) {
          this.Parent = options.parent;
          this.bindingDepth = (options.parent.bindingDepth || 0) + 1;
        }
        if (options.context) this.Context = new Set(options.context);
        if (options.generator) {
          this.FncElements = options.generator;
          this.Elements = [];
          GAddTo(this.Elements, this.FncElements, this);
        }
        privateProperties.setProperty(this, "GenerationFinish", true);
        if (options.refresh === undefined || options.refresh === true)
          this.refresh();
      }
    } catch (error) {
      // The caller cannot dispose an instance whose construction never returned.
      // Cleanup failures must not replace the original directive/generator error.
      try { this.destroy(); }
      catch (cleanupError) { console.error('[GTPL] Error cleaning failed construction:', cleanupError); }
      throw error;
    }
  }

  getValue(key: any): any {
    const ref = this.Root;
    if (key == 'this')
      return ref;
    if (ref && (key in ref))
      return ref[key];
    if (this.Parent)
      return this.Parent.getValue(key);
    return undefined;
  }

  getGtplRoot(): GTpl {
    if (this.Parent) return this.Parent.getGtplRoot();
    return this;
  }

  getRoot(): any {
    if (this.Parent) return this.Parent.getRoot();
    return this.Root;
  }

  getContext(key: string): GTpl {
    if (key == 'this')
      return this;
    if (this.Context && this.Context.has(key))
      return this;
    if (this.Parent)
      return this.Parent.getContext(key);
    return this.getGtplRoot();
  }

  addBind(bind: IBindObject) {
    if (this.checkDestroyed('addBind')) return;
    initialBindings.add(bind);
    if (bind.type === BindTypes.IS && bind.mark) persistentMarks.add(bind.mark);
    if (!checkBindElements(this, bind)) {
      if (!checkBindEvent(this, bind)) {
        if (!checkBindFormula(this, bind)) {
          if (!checkBind(this, bind)) {
            this.BindConst.add(bind);
          }
        }
      }
    }
    if (privateProperties.getProperty(this, "GenerationFinish")) {
      this.queueChange(TypeEventProxyHandler.FORCE_REFRESH_ROOT, bind, undefined, undefined, true);
    }
  }

  private checkDestroyed(operation: string): boolean {
    if (this.isDestroyed) {
      console.warn(`[GTPL] Cannot perform ${operation} on destroyed component`, this.ID);
      return true;
    }
    return false;
  }

  destroy(elements = true) {

    if (this.isDestroyed) {
      console.warn('[GTPL] Component already destroyed', this.ID);
      return;
    }

    // Cleanup can destroy an ancestor, which visits this child again.
    this.isDestroyed = true;

    if (this.cleanupCallbacks && this.cleanupCallbacks.size > 0) {
      this.cleanupCallbacks.forEach(callback => {
        try {
          callback();
        } catch (error) {
          console.error('[GTPL] Error in cleanup callback:', error);
        }
      });
      this.cleanupCallbacks.clear();
    }

    // A child can render outside its original insertion marker (g-is/switch).
    // Dispose its rendered roots before clearing its element references.
    this.GtplChilds.forEach(child => {
      if (!child.isDestroyed) child.destroy(elements);
    });

    this.GtplChilds.clear();

    if (this.BindDef) {
      for (const objdef of this.BindDef) {
        const descriptor = reactiveDescriptors.get(objdef);
        if (descriptor) {
          descriptor.active = false;
          const previous = descriptor.original?.get && reactiveGetters.get(descriptor.original.get);
          previous?.successors?.delete(descriptor);
          descriptor.successors?.forEach(successor => {
            successor.original = descriptor.original;
            if (previous) (previous.successors || (previous.successors = new Set())).add(successor);
          });
          descriptor.successors?.clear();
        }
        if (descriptor && this.Root && Object.getOwnPropertyDescriptor(this.Root, objdef.key)?.get === descriptor.get) {
          let original = descriptor.original;
          while (original?.get) {
            const previous = reactiveGetters.get(original.get);
            if (!previous || previous.active) break;
            original = previous.original;
          }
          try {
            Object.defineProperty(this.Root, objdef.key, original && !('value' in original)
              ? original
              : { configurable: true, enumerable: true, writable: true, ...original, value: toRaw(objdef.val) });
            if (original?.set) original.set.call(this.Root, toRaw(objdef.val));
          } catch (error) {
            console.error('[GTPL] Error restoring reactive property:', error);
          }
        }
        reactiveDescriptors.delete(objdef);
        unGProxy(objdef.val, this.BoundEventProxy, objdef);
      }
      this.BindDef.clear();
    }

    const localBinds = new Set<IBindObject>();
    const renderedRoots = new Set<any>();
    const rememberRenderedRoot = (bind: IBindObject) => {
      if (!elements || (bind.gtpl && bind.gtpl !== this)) return;
      if (
        bind.ele &&
        (bind.type === BindTypes.IF || bind.type === BindTypes.NOTIF ||
          bind.type === BindTypes.SWITCH || bind.type === BindTypes.IS)
      ) renderedRoots.add(bind.ele);
    };
    if (this.BindTree) {
      Object.keys(this.BindTree).forEach((key) => {
        collectBindsFromTree(this.BindTree[key], localBinds);
      });
    }
    if (this.BindConst) {
      this.BindConst.forEach((bind) => localBinds.add(bind));
    }
    localBinds.forEach((bind) => {
      rememberRenderedRoot(bind);
      delBind(this, bind);
    });

    if (this.BindMap) {
      for (const [bind, ctxgtpl] of this.BindMap) {
        rememberRenderedRoot(bind);
        delBind(ctxgtpl, bind);
        additionalBindContexts.get(this)?.get(bind)?.forEach(context => {
          if (context !== ctxgtpl) delBind(context, bind);
        });
      }
      this.BindMap.clear();
    }
    additionalBindContexts.delete(this);

    if (elements) {
      removeElements(this.Elements);
      // Inherited structural bindings live in an ancestor's bind tree, so
      // their inserted roots may not appear in this instance's Elements list.
      renderedRoots.forEach(root => removeElements(root));
      if (this.RenderElements) {
        const entries = Array.isArray(this.Elements) ? this.Elements.length : 1;
        for (let index = 0; index < entries; index++) {
          const bind: IBindObject = this.RenderElements[index];
          if (bind) {
            if (bind.ele)
              removeElements(bind.ele);
            if (bind.eles)
              removeElements(bind.eles);
          }
        }
        this.RenderElements = null;
      }
    }

    if (this.watchers)
      this.watchers.clear();
    this.watchers = null!;

    // Cleanup total
    this.Elements = null!;
    this.Root = null!;
    this.BindTree = null!;
    this.BindConst = null!;
    this.Context = null!;
    this.Parent = null!;

  }

  onCleanup(callback: () => void): void {
    if (this.isDestroyed)
      return;
    if (typeof callback !== 'function')
      return;
    this.cleanupCallbacks.add(callback);
  }

  refresh() {
    for (let objdef of this.BindDef) {
      this.eventPRoxy(TypeEventProxyHandler.FORCE_REFRESH_ROOT, [], undefined, objdef);
    }
    if (this.BindMap) {
      for (let [bind, gtpl] of this.BindMap) {
        if (gtpl instanceof GTpl) gtpl.queueChange(TypeEventProxyHandler.FORCE_REFRESH_MAP, bind, undefined, undefined, true);
        else gtpl.launchChange(TypeEventProxyHandler.FORCE_REFRESH_MAP, bind);
      }
    }
    if (this.BindConst) {
      for (let bind of this.BindConst) {
        this.queueChange(TypeEventProxyHandler.FORCE_REFRESH_CONST, bind, undefined, undefined, true);
      }
    }
  }

  /** Wait for the initial bindings and generated children. Mount before awaiting. */
  ready(): Promise<void> {
    if (!this.initialReady) {
      this.initialReady = new Promise<void>((resolve, reject) => {
        const finish = (error?: { error: unknown }) => {
          if (this.initialState.settled) return;
          this.initialState.settled = true;
          this.initialState.reject = undefined;
          this.cleanupCallbacks.delete(cancel);
          if (error) reject(error.error);
          else resolve();
        };
        const cancel = () => finish({ error: new Error('[GTPL] Component destroyed before ready') });
        this.initialState.reject = error => finish({ error });
        this.onCleanup(cancel);
        this.waitInitialRender().then(() => finish(), error => finish({ error }));
      });
    }
    return this.initialReady;
  }

  private async waitInitialRender(): Promise<void> {
    do {
      if (this.isDestroyed)
        throw new Error('[GTPL] Component destroyed before ready');
      if (this.initialState.failure)
        throw this.initialState.failure.error;
      const state = this.initialState;
      if (!state.pending) return;
      if (!state.idle) state.idle = new Promise<void>(resolve => { state.resolveIdle = resolve; });
      await state.idle;
      // Updates can create children or register more bindings while rendering.
    } while (true);
  }

  private trackInitialUpdate(job: PendingBindingChange, owner: GTpl) {
    const states = job.initialStates || (job.initialStates = new Set());
    const collect = (context: GTpl) => {
      while (context) {
        const state = context.initialState;
        if (!state.settled && !states.has(state)) {
          states.add(state);
          state.pending++;
        }
        context = context.Parent as GTpl;
      }
    };
    collect(this);
    if (owner !== this) collect(owner);
  }

  private processRenderAndApply(ele: Node | any[], applyFn: (ele: Node | any[], arr: any, ctx: any) => void) {
    if (this.checkDestroyed('addBind')) return;
    if (this.RenderElements) {
      const render_arr: any[] = [];
      const arr = Array.isArray(this.Elements) ? this.Elements : [this.Elements];
      arr.forEach((element: Node, index: number) => {
        const bind: IBindObject | undefined = this.RenderElements[index];
        if (!bind) {
          render_arr.push(element);
          return;
        }
        if (bind.ele) {
          const range = Array.isArray(bind.ele) ? fragmentRanges.get(bind.ele) : undefined;
          if (range) range.hidden = false;
          render_arr.push(Array.isArray(bind.ele) ? fragmentNodes(bind.ele) : bind.ele);
          if (persistentMarks.has(bind.mark)) render_arr.push(bind.mark);
        } else if (bind.eles) {
          bind.eles.forEach((gtpl: IGtplObject) => gtpl.addTo(render_arr));
          render_arr.push(bind.mark);
        }
      });
      applyFn(ele, render_arr, this);
    } else {
      applyFn(ele, fragmentNodes(this.Elements), this);
    }
  }

  addTo(ele: Node | any[]) {
    this.processRenderAndApply(ele, GAddTo);
  }

  insertAfterTo(ele: Node | any[]) {
    this.processRenderAndApply(ele, GInsertAfterTo);
  }

  insertBeforeTo(ele: Node | any[]) {
    this.processRenderAndApply(ele, GInsertBeforeTo);
  }

  watch(path: string | string[], cb: (info: any) => void) {
    if (this.isDestroyed) return () => { };
    const key = Array.isArray(path) ? path.join(".") : path;
    let set = this.watchers.get(key);
    if (!set) this.watchers.set(key, set = new Set());
    set.add(cb);
    const unwatch = () => {
      this.cleanupCallbacks.delete(unwatch);
      if (!this.watchers) return;
      const s = this.watchers.get(key);
      if (!s) return;
      s.delete(cb);
      if (!s.size) this.watchers.delete(key);
    };
    this.onCleanup(unwatch);
    return unwatch;
  }

  private emitWatchers(type: TypeEventProxyHandler, pathArr: PathProxyHandler, value: any, objRef: any) {
    if (!this.watchers || this.watchers.size === 0) return;
    if (!pathArr || !pathArr.length) return;
    if ((pathArr as Array<string | number | symbol>).some((p: string | number | symbol) => typeof p === "symbol")) return;
    const full = pathArr.map(String).join(".");
    if (!full) return;
    const callKey = (key: string) => {
      if (this.isDestroyed) return;
      const set = this.watchers?.get(key);
      if (!set) return;
      for (const cb of set) {
        if (this.isDestroyed) return;
        try {
          cb({ type, path: full, value, objRef, watch: key });
        } catch (e) {
          console.error("[GTPL watch] error", e);
        }
      }
    };
    callKey(full);
    const prefixes: string[] = [];
    for (let end = full.lastIndexOf('.'); end >= 0; end = full.lastIndexOf('.', end - 1)) {
      const prefix = full.slice(0, end);
      prefixes.push(prefix);
      callKey(prefix);
      if (end === 0) break;
    }
    for (const prefix of prefixes) callKey(prefix + '.*');
    callKey("*");
  }

  eventPRoxy(type: TypeEventProxyHandler, path: PathProxyHandler, value: any, objRef: any) {
    if (this.isDestroyed) return;
    this.emitWatchers(type, path, value, objRef);
    if (this.isDestroyed) return;
    const proxyPath = Array.isArray(path) ? path : [];
    GTpl.queueBindings(this, this.BindTree[objRef.key], type, proxyPath, 1);
  }

  private static queueBindings(context: GTpl, tree: any, type: TypeEventProxyHandler, path: string[], depth: number) {
    if (!tree) return;
    if (tree.me)
      for (const bind of tree.me) context.queueChange(type, bind, path, undefined, true, depth);
    if (tree.tree) {
      const changed = path[depth];
      if (changed !== undefined) {
        GTpl.queueBindings(context, tree.tree[changed], type, path, depth + 1);
      } else {
        for (const key in tree.tree)
          GTpl.queueBindings(context, tree.tree[key], type, path, depth + 1);
      }
    }
  }

  launchChange(
    type: TypeEventProxyHandler,
    bind: IBindObject,
    path?: string[],
    value?: any
  ): Promise<void> {
    return this.queueChange(type, bind, path, value)!;
  }

  private queueChange(
    type: TypeEventProxyHandler,
    bind: IBindObject,
    path?: string[],
    value?: any,
    automatic: boolean = false,
    pathOffset: number = 0
  ): Promise<void> | undefined {
    if (this.isDestroyed || bind.gtpl?.isDestroyed || bind.type === BindTypes.EVENT)
      return automatic ? undefined : Promise.resolve();
    let job = pendingBindingChanges.get(bind);
    const relativeLength = path ? path.length - pathOffset : 0;
    const listUpdate = automatic && bind.type === BindTypes.FOR && isDirectList(bind) &&
      (type === TypeEventProxyHandler.SET || type === TypeEventProxyHandler.UNSET) && relativeLength > 0;
    const rowIndex = listUpdate && typeof path![pathOffset] !== 'symbol' &&
      /^(0|[1-9]\d*)$/.test(String(path![pathOffset])) ? Number(path![pathOffset]) : undefined;
    const listNestedOnly = rowIndex !== undefined && relativeLength > 1;

    if (job) {
      if (bind.type === BindTypes.FOR) {
        job.listUpdate = job.listUpdate && listUpdate;
        job.listNestedOnly = job.listNestedOnly && listNestedOnly;
      }
      // Reconcile the final state once. Explicit index assignments are kept
      // separately because assigning the same row can expose raw mutations.
      job.type = TypeEventProxyHandler.FORCE_REFRESH_ROOT;
      job.path = undefined;
      job.value = undefined;
    } else {
      // Reuse pending jobs, but a request superseding running work gets a new
      // identity. No numeric revision can be reused after the binding is idle.
      const previous = currentBindingChanges.get(bind);
      if (previous) {
        if (previous.initialStates?.size) finishInitialUpdate(previous);
        previous.resolve?.();
      }
      job = { context: this, type, path: relativeLength > 0 ? path!.slice(pathOffset) : undefined, value, reportErrors: false };
      if (bind.type === BindTypes.FOR) { job.listUpdate = listUpdate; job.listNestedOnly = listNestedOnly; }
      pendingBindingChanges.set(bind, job);
      currentBindingChanges.set(bind, job);
    }
    const owner = (bind.gtpl || this) as GTpl;
    if (rowIndex !== undefined) {
      (job.listTouched || (job.listTouched = new Set())).add(rowIndex);
      if (type === TypeEventProxyHandler.SET && relativeLength === 1)
        (job.listIndices || (job.listIndices = new Set())).add(rowIndex);
    }
    // A merged job already tracks this caller's ancestors; avoid locating the
    // root again on every notification in a synchronous burst.
    const tracked = job.initialStates?.has(this.initialState);
    const initial = job.checkedCaller === this ? !!job.initialStates?.size :
      tracked || !this.getGtplRoot().initialState.settled ||
      (owner !== this && !owner.getGtplRoot().initialState.settled) ||
      (!owner.initialState.settled && initialBindings.has(bind));
    job.checkedCaller = this;
    if (!automatic) bindingChangePromise(job);
    if (initial && !tracked) this.trackInitialUpdate(job, owner);
    if (automatic && !initial) {
      job.reportErrors = true;
      observeBindingErrors(job);
    }
    if (activeBindingFlush && !activeBindingFlush.seen.has(bind)) {
      GTpl.enqueueFlushBinding(bind, job);
    }
    if (!activeBindingFlush && !bindingFlushScheduled) {
      bindingFlushScheduled = true;
      queueMicrotask(GTpl.flushChanges);
    }
    return job.promise;
  }

  private static flushChanges() {
    bindingFlushScheduled = false;
    activeBindingFlush = { queues: [], positions: [], seen: new Set(), depth: 0 };
    for (const [bind, job] of pendingBindingChanges) GTpl.enqueueFlushBinding(bind, job);
    // Reconcile ancestors before descendants, including intermediate structures
    // newly invalidated by a parent's row replacement. Each binding runs at most
    // once per flush; a self-invalidating effect continues in the next microtask.
    while (activeBindingFlush.depth < activeBindingFlush.queues.length) {
      const depth = activeBindingFlush.depth;
      const queue = activeBindingFlush.queues[depth];
      const position = activeBindingFlush.positions[depth] || 0;
      if (!queue || position >= queue.length) {
        activeBindingFlush.depth++;
        continue;
      }
      const bind = queue[position];
      activeBindingFlush.positions[depth] = position + 1;
      const job = pendingBindingChanges.get(bind);
      if (!job) continue;
      pendingBindingChanges.delete(bind);
      if (job.context.isDestroyed || bind.gtpl?.isDestroyed) {
        finishBindingChange(bind, job);
        continue;
      }
      try {
        const update = job.context.applyChange(job.type, bind, job.path, job.value, job);
        if (isPromiseLike(update)) Promise.resolve(update).then(
          () => finishBindingChange(bind, job), error => finishBindingChange(bind, job, { error }));
        else finishBindingChange(bind, job);
      } catch (error) {
        finishBindingChange(bind, job, { error });
      }
    }
    activeBindingFlush = undefined;
    if (pendingBindingChanges.size && !bindingFlushScheduled) {
      bindingFlushScheduled = true;
      queueMicrotask(GTpl.flushChanges);
    }
  }

  private static enqueueFlushBinding(bind: IBindObject, job: PendingBindingChange) {
    const flush = activeBindingFlush!;
    const depth = ((bind.gtpl || job.context) as GTpl).bindingDepth;
    (flush.queues[depth] || (flush.queues[depth] = [])).push(bind);
    flush.seen.add(bind);
    if (depth < flush.depth) flush.depth = depth;
  }

  private applyChange(
    type: TypeEventProxyHandler,
    bind: IBindObject,
    path: string[] | undefined,
    value: any,
    job: PendingBindingChange
  ): void | Promise<void> {
    const result = calculateBind(this, bind, value);
    if (isPromiseLike(result))
      return Promise.resolve(result).then(value => this.applyResult(type, bind, path, value, job));
    return this.applyResult(type, bind, path, result, job);
  }

  private applyResult(
    type: TypeEventProxyHandler,
    bind: IBindObject,
    path: string[] | undefined,
    result: any,
    job: PendingBindingChange
  ): void | Promise<void> {
    if (this.isDestroyed || bind.gtpl?.isDestroyed || currentBindingChanges.get(bind) !== job) return;
    let incremental = false;
    let nestedListHandled = false;
    if (bind.type === BindTypes.FOR) {
      const rows = toRaw(result);
      const previous = directListStates.get(bind);
      if (isDirectList(bind) && Array.isArray(rows)) {
        let ordinary = false;
        if (job.listUpdate && previous?.rows === rows && previous.ordinary && job.listTouched) {
          ordinary = true;
          for (const index of job.listTouched) {
            const descriptor = Object.getOwnPropertyDescriptor(rows, index);
            if (descriptor && (!('value' in descriptor) || !isOrdinaryData(descriptor.value))) {
              ordinary = false;
              break;
            }
          }
        } else ordinary = isOrdinaryData(rows);
        directListStates.set(bind, { rows, ordinary });
        incremental = !!job.listUpdate && ordinary;
        nestedListHandled = incremental && !!job.listNestedOnly && previous?.rows === rows && bind.eles?.length === rows.length;
      } else directListStates.delete(bind);
      // Full reconciliation may invoke arbitrary getters and cleanup callbacks;
      // snapshot those rows before revocation. Ordinary data can be read directly.
      if (Array.isArray(rows)) result = incremental ? rows : Array.from(rows, row => toRaw(row));
    }
    let gtpl: IGtplObject | Promise<IGtplObject> = this;
    switch (bind.type) {
      case BindTypes.TEXT: gtpl = updateTEXTbind(type, this, bind, result, path); break;
      case BindTypes.ATTR: gtpl = updateATTRbind(type, this, bind, result, path); break;
      case BindTypes.INNER: gtpl = updateINNERbind(type, this, bind, result, path); break;
      case BindTypes.STYLE: gtpl = updateSTYLEbind(type, this, bind, result, path); break;
      case BindTypes.IF:
      case BindTypes.NOTIF: gtpl = updateIFbind(type, this, bind, result, path); break;
      case BindTypes.FOR:
        if (!nestedListHandled) gtpl = updateFORbind(type, this, bind, result, path, incremental, job.listIndices);
        break;
      case BindTypes.SWITCH: gtpl = updateSWITCHbind(type, this, bind, result, path, job); break;
      case BindTypes.IS: gtpl = updateISbind(type, this, bind, result, path); break;
    }
    if (isPromiseLike(gtpl)) {
      return Promise.resolve(gtpl).then(context => {
        if (!context.isDestroyed && !this.isDestroyed && !bind.gtpl?.isDestroyed && currentBindingChanges.get(bind) === job)
          checkRenderElements(context, bind);
      });
    }
    if (!gtpl.isDestroyed && currentBindingChanges.get(bind) === job) checkRenderElements(gtpl, bind);
  }
}
